def _history_resource_identity(self, state):
    if not isinstance(state, dict):
        return None
    provider = self._resource_provider_key(state.get("resourceProvider"))
    mode = str(state.get("resourceMode") or "").strip().lower()
    resource_id = str(state.get("resourceId") or "").strip()
    return (provider, mode, resource_id) if provider and mode and resource_id else None

@staticmethod
def _history_drive_identity(state):
    if not isinstance(state, dict):
        return None
    share_key = str(state.get("driveShareKey") or "").strip()
    path = unicodedata.normalize("NFKC", str(state.get("drivePath") or ""))
    path = re.sub(r"/+", "/", path.replace("\\", "/")).rstrip("/").casefold()
    return (share_key, path) if share_key and path else None

